const el=(t,a={},p)=>{const e=document.createElementNS(NS,t);for(const k in a)e.setAttribute(k,a[k]);if(p)p.appendChild(e);return e};
const byId={};MAP.nodes.forEach(n=>byId[n.id]=n);

/* ---- network map ---- */
function drawMap(svg,o){
  const pre=o.pre,g0=el("g",{class:"m-grid"},svg);
  for(let x=40;x<860;x+=70)el("line",{x1:x,y1:0,x2:x,y2:770},g0);
  for(let y=30;y<770;y+=70)el("line",{x1:0,y1:y,x2:860,y2:y},g0);
  const out=el("path",{d:MAP.d,class:"m-out",pathLength:1},svg);
  const eg=el("g",{},svg),pg=el("g",{},svg),ng=el("g",{},svg),edges=[],nodes=[];
  MAP.nodes.forEach((n,i)=>{
    if(!n.p)return;const a=byId[n.p],dx=n.x-a.x,dy=n.y-a.y,len=Math.hypot(dx,dy);
    const mx=(a.x+n.x)/2-dy*.16,my=(a.y+n.y)/2+dx*.16;
    const e=el("path",{id:pre+"e"+i,d:`M${a.x},${a.y}Q${mx},${my} ${n.x},${n.y}`,class:"m-edge"+(n.t==="whale"?" w":""),pathLength:1},eg);
    e.dataset.t=n.t;edges.push({e,n,len});
  });
  MAP.nodes.forEach(n=>{
    const og=el("g",{transform:`translate(${n.x},${n.y})`},ng);
    const g=el("g",{class:"m-node "+n.t},og);
    const inner=el("g",{},g);
    if(n.t==="hub")el("circle",{r:9,class:"m-halo"},inner);
    el("circle",{r:n.t==="hub"?9:n.t==="whale"?7:4,class:"c"},inner);
    if(n.t!=="agent"||o.allLabels){const t=el("text",{y:n.t==="agent"?-9:-13,"text-anchor":"middle"},inner);t.textContent=n.name}
    g.dataset.t=n.t;nodes.push(g);
  });
  return {out,edges,nodes,pg,pre};
}
function pulses(m){
  m.edges.forEach(({e,n},i)=>{
    if(n.t==="agent"&&i%2)return;
    const c=el("circle",{r:n.t==="whale"?3.2:2.4,class:"m-pulse"},m.pg);
    const am=el("animateMotion",{dur:(3+Math.random()*3).toFixed(1)+"s",begin:(Math.random()*3).toFixed(1)+"s",repeatCount:"indefinite",keyPoints:"0;1",keyTimes:"0;1",calcMode:"linear"},c);
    el("mpath",{href:"#"+e.id},am);
  });
}
function reveal(m,{outDur=2200,delay=0}={}){
  m.out.style.transition=`stroke-dashoffset ${outDur}ms ease ${delay}ms`;
  requestAnimationFrame(()=>m.out.style.strokeDashoffset=0);
  const hubs=m.nodes.filter(n=>n.dataset.t==="hub"),rest=m.nodes.filter(n=>n.dataset.t!=="hub");
  hubs.forEach(n=>setTimeout(()=>n.classList.add("on"),delay+outDur*.6));
  m.edges.forEach(({e,n},i)=>{
    const d=delay+outDur*.8+i*70;
    e.style.transition=`stroke-dashoffset 900ms ease ${d}ms, opacity 400ms ${d}ms`;
    requestAnimationFrame(()=>{e.style.strokeDashoffset=0;e.style.opacity=n.t==="whale"?.85:.55});
  });
  rest.forEach((g,i)=>setTimeout(()=>g.classList.add("on"),delay+outDur*.8+i*70+500));
  setTimeout(()=>pulses(m),delay+outDur*.8+MAP.nodes.length*70+900);
}
