/* ---- intro timeline ---- */
const $=id=>document.getElementById(id);
const reduce=matchMedia("(prefers-reduced-motion: reduce)").matches;
let entered=false,timers=[];
const at=(ms,f)=>timers.push(setTimeout(f,reduce?0:ms));
at(500,()=>$("logo").classList.add("on"));
at(2000,()=>{$("ttl").classList.add("on")});
at(3300,()=>{$("under").classList.add("on");$("sub").classList.add("on")});
at(2600,()=>{$("mapwrap").classList.add("on");reveal(m1,{delay:0})});
at(6600,()=>{$("enter").classList.add("on");$("bar").classList.add("run")});
at(10000,enter);
function enter(){
  if(entered)return;entered=true;timers.forEach(clearTimeout);
  $("intro").classList.add("leave");$("app").classList.add("on");
  startDash();
  setTimeout(()=>{$("intro").style.display="none"},950);
}
$("intro").addEventListener("click",()=>{ if(!$("enter").classList.contains("on")&&!entered){ /* skip ahead: show everything */ }; enter()});
$("goBtn").addEventListener("click",e=>{e.stopPropagation();enter()});

/* ---- dashboard ---- */
let dashStarted=false;
function startDash(){
  if(dashStarted)return;dashStarted=true;
  // persian digits + separators for static text
  const w=document.createTreeWalker($("app"),NodeFilter.SHOW_TEXT);const ns=[];while(w.nextNode())ns.push(w.currentNode);
  ns.forEach(n=>{if(/\d/.test(n.nodeValue))n.nodeValue=fa(n.nodeValue.replace(/(?<=\d),(?=\d)/g,"،"))});
  document.querySelectorAll("#app [title],#app [aria-label]").forEach(e=>{["title","aria-label"].forEach(a=>{if(e.hasAttribute(a))e.setAttribute(a,fa(e.getAttribute(a)))})});
  bundle();chart();initApp();
  const m2=drawMap($("map2"),{pre:"b",allLabels:false});
  reveal(m2,{outDur:1400,delay:500});
  $("seg").addEventListener("click",e=>{
    const b=e.target.closest("button");if(!b)return;
    [...$("seg").children].forEach(x=>x.setAttribute("aria-pressed",x===b));
    const f=b.dataset.f;
    m2.nodes.forEach(g=>g.style.opacity=(f==="all"||g.dataset.t==="hub"||g.dataset.t===f)?"":".12");
    m2.edges.forEach(({e,n})=>e.style.opacity=(f==="all"||n.t===f)?(n.t==="whale"?.85:.55):.06);
  });
}
function bundle(){
  // integer toman math. Cashless needed = ceil(requiredMargin / marginPerCashless)
  const n=10,posCur=36e6,posTarget=33e6,posCost=29e6,csMarket=10.5e6,csSale=9e6,csCost=6.5e6;
  const reqMargin=n*(posCur-posTarget),csMargin=csSale-csCost,qty=Math.ceil(reqMargin/csMargin);
  const bundleP=n*posTarget+qty*csSale,separate=n*posCur+qty*csSale,gm=n*(posTarget-posCost)+qty*csMargin;
  const ok=posTarget>=posCost&&csSale>=csCost&&csSale<csMarket&&gm>=0;
  const rows=[["قیمت فعلی کارتخوان",faSep(posCur)],["قیمت هدف کارتخوان",faSep(posTarget)],["تخفیف کل کارتخوان",faSep(reqMargin)],["حاشیه سود هر کشلس",faSep(csMargin)],["کشلس لازم",fa(qty)+" دستگاه"],["قیمت بسته",faSep(bundleP)],["صرفه‌جویی نسبت به خرید جدا",faSep(separate-bundleP)]];
  $("bundle").innerHTML=rows.map(r=>`<span>${r[0]}</span><span>${r[1]}</span>`).join("");
  $("bundleTot").innerHTML=`<span>${ok?"سود ناخالص بسته":"هشدار: بسته زیان‌ده است"}</span><b style="font-weight:400">${faSep(gm)} تومان</b>`;
  if(!ok)$("bundleTot").style.cssText="background:var(--bad-bg);color:var(--bad)";
}
function chart(){
  const data=[["خرداد",6],["تیر",8],["مرداد",9],["شهریور",7],["مهر",7]],T=10,W=520,H=210,L=28,B=34,Tp=14,bw=46;
  const s=el("svg",{viewBox:`0 0 ${W} ${H}`,role:"img","aria-label":"فروش ماهانه کارتخوان، هدف ۱۰ دستگاه"});
  const y=v=>H-B-(H-B-Tp)*v/12,step=(W-L)/data.length;
  [0,4,8,12].forEach(v=>{el("line",{x1:L,x2:W,y1:y(v),y2:y(v),stroke:"#d5dbe2","stroke-width":1},s);const t=el("text",{x:L-6,y:y(v)+4,"text-anchor":"end"},s);t.textContent=fa(v)});
  const tl=el("line",{x1:L,x2:W,y1:y(T),y2:y(T),stroke:"#33373d","stroke-width":1.4,"stroke-dasharray":"5 4"},s);
  const tt=el("text",{x:W,y:y(T)-5,"text-anchor":"end"},s);tt.textContent="هدف ماهانه ۱۰ دستگاه";
  data.forEach(([m,v],i)=>{
    const cx=W-step*(i+.5),cur=i===data.length-1,h=y(0)-y(v);
    const r=el("path",{d:`M${cx-bw/2},${y(0)}V${y(v)+4}Q${cx-bw/2},${y(v)} ${cx-bw/2+4},${y(v)}H${cx+bw/2-4}Q${cx+bw/2},${y(v)} ${cx+bw/2},${y(v)+4}V${y(0)}Z`,fill:cur?"#0f4c9a":"#9aa6b6",tabindex:0},s);
    r.addEventListener("mousemove",e=>tip(e,`${m}: ${fa(v)} دستگاه`));r.addEventListener("mouseleave",()=>$("tip").classList.remove("on"));
    r.addEventListener("focus",()=>toast(`${m}: ${fa(v)} دستگاه`));
    const vt=el("text",{x:cx,y:y(v)-6,"text-anchor":"middle",style:"fill:#33373d"},s);vt.textContent=fa(v);
    const mt=el("text",{x:cx,y:H-12,"text-anchor":"middle"},s);mt.textContent=m;
  });
  $("chart").appendChild(s);
}
function tip(e,t){const p=$("tip");p.textContent=t;p.style.left=(e.clientX+12)+"px";p.style.top=(e.clientY-34)+"px";p.classList.add("on")}
let tt2;function toast(t){const e=$("toast");e.textContent=t;e.classList.add("on");clearTimeout(tt2);tt2=setTimeout(()=>e.classList.remove("on"),2600)}


