let MCB=[],MID=0;
function modal({title,body,actions=[],wide=false}){MID++;MCB=actions.map(a=>a.fn);const m=$("modal");m.innerHTML=`<div class="mbox${wide?" wide":""}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="mh"><h3>${title}</h3><button class="x" type="button" data-act="mclose" aria-label="بستن">×</button></div><div class="mb">${body}</div>${actions.length?`<div class="mf">${actions.map((a,i)=>`<button type="button" class="b ${a.cls||""}" data-mi="${i}">${a.label}</button>`).join("")}</div>`:""}</div>`;m.hidden=false;faDom(m)}
function mclose(){$("modal").hidden=true;$("modal").innerHTML="";MCB=[]}
const confirmBox=(title,msg,fn,label="تأیید و ثبت")=>modal({title,body:`<p class="mp">${msg}</p>`,actions:[{label:"انصراف",cls:"ghost"},{label,cls:"pri",fn}]});
