function textModal(title,text){modal({title,wide:true,body:`<textarea class="csv" readonly id="csvBox">${esc(text)}</textarea><p class="lbl">دانلود مستقیم فایل در این نسخه ممکن نیست؛ متن را کپی کنید و در Excel جای‌گذاری کنید.</p>`,actions:[{label:"بستن",cls:"ghost"},{label:"کپی متن",cls:"pri",fn:()=>{copyText(text);return false}}]});setTimeout(()=>{const b=$("csvBox");b&&b.select()},50)}
