 if(v==="dash")renderDash();else if(VIEWS[v]){const c=document.querySelector(`[data-view="${v}"]`);c.innerHTML=VIEWS[v]();faDom(c);VIEWS[v].after&&VIEWS[v].after(c)}
 const cc=sum(S.cart,l=>l.qty);const cb=$("cartBadge");cb.textContent=cc?fa(cc):"";cb.hidden=!cc;
