/* ---------- سبد خرید و پرداخت ---------- */
function cartCalc(){
  // اعمال قیمت پویا روی هر خط سبد
  S.cart.forEach(l => {
    if (!l.bundle) { // بسته‌ها قیمت ثابت دارند
      const dp = dynamicUnitPrice(l.sku, l.qty);
      l.price = dp.final;
      l._pricing = dp;
    }
  });

  const c = calc(S.cart);
  let disc = 0, msg = "";
  const summary = pricingSummary();
  const ratio = summary.ratioCheck;

  // کد تخفیف دستی (با رعایت حداقل حاشیه)
  if (S.code) {
    const maxD = sum(S.cart, l => l.qty * Math.max(0, (l.price ?? P(l.sku).price) - P(l.sku).cost));
    disc = Math.min(Math.round(c.sub * CODES[S.code].pct), maxD);
    if (disc < Math.round(c.sub * CODES[S.code].pct)) msg = "تخفیف کد تا مرز بهای تمام‌شده محدود شد";
  }

  // پیام‌های شفاف برای نماینده
  const messages = [];
  if (summary.combinedDiscount > 0) {
    messages.push(`تخفیف حجمی + وفاداری: ${(summary.combinedDiscount*100).toFixed(0)}٪`);
  }
  if (!ratio.ok) {
    messages.push(ratio.message);
  }
  if (msg) messages.push(msg);

  const f = calc(S.cart, disc);
  return {
    ...f,
    msg: messages.join(" · "),
    pricing: summary,
    ratio
  };
}
