function placeOrder(c,w,cr,gw,fromQuote){
 const y=jd().slice(0,4);const seq=S.orders.length+409;const id=`TT-${y}-${pad(seq).padStart(4,"0")}`;const now=jt();
 const lines=S.cart.map(l=>({...l,price:l.price??P(l.sku).price}));
 const o={id,date:jd(),status:"processing",lines,pay:{wallet:w,credit:cr,gateway:gw},track:null,note:"",tl:[["awaiting_payment",now,"ثبت سفارش"]]};
 if(cr>0)o.tl.push(["credit_approved",now,`${n$(cr)} تومان از اعتبار شما استفاده شد`]);
 o.tl.push(["paid",now,"پرداخت و تسویه ثبت شد"],["processing",now,"سفارش وارد صف پردازش شد"]);
 if(w>0)wtx("خرید از کیف پول",-w,id);
 if(cr>0){S.credit.used+=cr;S.ledger.unshift({t:jd(),order:id,amt:cr,type:"استفاده"})}
 lines.forEach(l=>P(l.sku).stock-=l.qty);
 S.orders.unshift(o);const iid="INV-"+id.slice(-4);
 S.invoices.unshift({id:iid,order:id,type:"invoice",date:jd(),due:jd(new Date(Date.now()+10*864e5)),lines,disc:c.disc,paid:c.total,cancelled:false});
 [["کیف پول",w],["اعتبار",cr],["درگاه آنلاین",gw]].filter(x=>x[1]>0).forEach((x,i)=>S.payments.unshift({id:"PY-"+(8900+S.payments.length+i),inv:iid,amt:x[1],m:x[0],t:now,rec:x[0]==="درگاه آنلاین"?"در انتظار تطبیق":"تطبیق‌شده"}));
 const posQ=sum(lines.filter(l=>P(l.sku).cat==="pos"),l=>l.qty);if(posQ)S.rewards.unshift({id:"RW-"+(3411+S.rewards.length),type:"فروش کارتخوان",desc:`${posQ} دستگاه · سفارش ${id}`,amt:posQ*REWARD_POS,status:"pending",ref:id});
 audit("سفارش",`ثبت ${id} به مبلغ ${n$(c.total)} تومان`);
 S.cart=[];S.code=null;S.codeUsed="";S.ui.payOpen=false;S.ui.ordSel=id;toast("سفارش ثبت شد");go("orders")}

/* ================= سفارش‌ها و رهگیری، پیش‌فاکتور و فاکتور ================= */
const ordTotal=o=>calc(o.lines,o.disc||0).total;
const ordLines=o=>o.lines.map(l=>`${P(l.sku).name.replace(/ [A-Z]\d+$/,"")} ${P(l.sku).sku} × ${fa(l.qty)}`).join("، ");
const ordShort=o=>{const pos=sum(o.lines.filter(l=>P(l.sku).cat==="pos"),l=>l.qty),cs=sum(o.lines.filter(l=>P(l.sku).cat==="cashless"),l=>l.qty),ac=sum(o.lines.filter(l=>P(l.sku).cat==="acc"),l=>l.qty);return[pos?`${fa(pos)} کارتخوان`:"",cs?`${fa(cs)} کشلس`:"",ac?`${fa(ac)} لوازم`:""].filter(Boolean).join(" + ")+(o.lines.some(l=>l.bundle)?" (بسته)":"")};
const stepsBar=s=>{const i=FLOW.indexOf(s);const n=["awaiting_payment","processing","packed","shipped","delivered"];const idx=n.findIndex(x=>FLOW.indexOf(x)>=FLOW.indexOf(s));const k=["cancelled","returned"].includes(s)?0:(FLOW.indexOf(s)<0?0:n.filter(x=>FLOW.indexOf(x)<=i).length);return`<div class="steps">${n.map((_,j)=>`<i class="${j<k?"d":""}"></i>`).join("")}</div>`};

VIEWS.orders=()=>{
 const sel=S.ui.ordSel&&S.orders.find(o=>o.id===S.ui.ordSel);
 if(sel)return orderDetail(sel);
 const f=S.ui.ordF,act=["awaiting_payment","paid","credit_approved","processing","packed","shipped"];
 const list=S.orders.filter(o=>f==="all"||(f==="active"&&act.includes(o.status))||(f==="done"&&["delivered","completed"].includes(o.status))||(f==="bad"&&["cancelled","returned"].includes(o.status)));
 const funnel=FLOW.slice(0,6).map(s=>[s,S.orders.filter(o=>FLOW.indexOf(o.status)>=FLOW.indexOf(s)).length]);
 return vhead("سفارش‌ها و رهگیری","وضعیت دقیق هر سفارش را همین‌جا ببینید؛ نیازی به تماس با شرکت نیست",`<button class="b pri" type="button" data-go="shop">سفارش جدید</button>`)+
 `<div class="grid4">${stat("کل سفارش‌ها",fa(S.orders.length))}${stat("در جریان",fa(S.orders.filter(o=>act.includes(o.status)).length),"تا تحویل")}${stat("در انتظار پرداخت",fa(S.orders.filter(o=>o.status==="awaiting_payment").length))}${stat("تحویل‌شده",fa(S.orders.filter(o=>["delivered","completed"].includes(o.status)).length))}</div>
 <section class="card">${seg("ordF",[["all","همه"],["active","در جریان"],["done","تحویل‌شده"],["bad","لغو و مرجوعی"]],f)}${list.length?`<div class="tw"><table><thead><tr><th>شماره</th><th>تاریخ</th><th>کالا</th><th>وضعیت</th><th>پیشرفت</th><th>مبلغ (تومان)</th><th></th></tr></thead><tbody>${list.map(o=>`<tr class="clk" data-act="oopen" data-id="${o.id}"><td class="n">${o.id}</td><td class="n">${o.date}</td><td>${ordShort(o)}</td><td>${stc(o.status)}</td><td>${stepsBar(o.status)}</td><td class="n">${n$(ordTotal(o))}</td><td><span class="link">جزئیات</span></td></tr>`).join("")}</tbody></table></div>`:empty("سفارشی در این دسته نیست")}</section>`;
};
function orderDetail(o){
 const c=calc(o.lines,o.disc||0),paid=o.pay.wallet+o.pay.credit+o.pay.gateway,inv=S.invoices.find(i=>i.order===o.id);
 const done=o.tl.map(t=>t[0]);const lastIdx=FLOW.indexOf(o.status);const future=["cancelled","returned"].includes(o.status)?[]:FLOW.filter((s,i)=>i>lastIdx&&s!=="awaiting_payment");
 const canCancel=["awaiting_payment","paid","credit_approved","processing","packed"].includes(o.status),canReturn=["delivered","completed"].includes(o.status),canAdv=!["cancelled","returned","completed"].includes(o.status)&&o.status!=="awaiting_payment";
 return vhead(`سفارش ${o.id}`,`ثبت‌شده در ${o.date}`,`<button class="b" type="button" data-act="oback">بازگشت به فهرست</button>`)+
 `<div class="bgrid"><section class="card"><h3>وضعیت و رهگیری ${stc(o.status)}</h3>
 ${o.note?`<div class="warnbox warn">${o.status==="cancelled"||o.status==="returned"?"دلیل":"توضیح شرکت"}: ${o.note}</div>`:""}
 ${o.track?`<div class="trk"><div><span class="lbl">شرکت حمل</span><b>${o.track.carrier}</b></div><div><span class="lbl">کد رهگیری</span><b class="n">${o.track.code}</b> <button class="link" type="button" data-act="copyv" data-v="${o.track.code}">کپی</button></div></div>`:`<p class="lbl">هنوز کد رهگیری صادر نشده است.</p>`}
 <ol class="tlv">${o.tl.map(t=>`<li class="d"><b>${ST[t[0]][0]}</b><span class="lbl">${t[1]}</span>${t[2]?`<span>${t[2]}</span>`:""}</li>`).join("")}${future.map(s=>`<li><b>${ST[s][0]}</b><span class="lbl">در انتظار</span></li>`).join("")}</ol>
 <div class="mrow">${canCancel?`<button class="b danger" type="button" data-act="ocancel" data-id="${o.id}">لغو سفارش</button>`:""}${canReturn?`<button class="b danger" type="button" data-act="oreturn" data-id="${o.id}">درخواست مرجوعی</button>`:""}${o.status==="awaiting_payment"?`<button class="b pri" type="button" data-act="opay" data-id="${o.id}">پرداخت سفارش</button>`:""}${inv?`<button class="b" type="button" data-act="invview" data-id="${inv.id}">مشاهده فاکتور</button>`:""}</div>
 ${canAdv?`<div class="demo"><span class="lbl">کنترل نمایشی (فقط برای آزمایش مسیر):</span><button class="b sm" type="button" data-act="oadv" data-id="${o.id}">پیشبرد وضعیت</button></div>`:""}</section>
 <section class="card"><h3>اقلام و پرداخت</h3><div class="tw"><table><tbody>${o.lines.map(l=>`<tr><td>${P(l.sku).name}${l.bundle?" "+chip("ok","بسته"):""}</td><td class="n">${fa(l.qty)} × ${n$(l.price)}</td><td class="n">${n$(l.qty*l.price)}</td></tr>`).join("")}</tbody></table></div>
 <div class="kvl"><span>جمع اقلام</span><span>${n$(c.sub)}</span>${c.disc?`<span>تخفیف</span><span>−${n$(c.disc)}</span>`:""}<span>ارزش افزوده</span><span>${n$(c.vat)}</span><span><b>مبلغ کل</b></span><span><b>${n$(c.total)}</b></span></div>
 <h4 class="h4">تفکیک پرداخت</h4><div class="kvl"><span>کیف پول</span><span>${n$(o.pay.wallet)}</span><span>اعتبار</span><span>${n$(o.pay.credit)}</span><span>درگاه آنلاین</span><span>${n$(o.pay.gateway)}</span><span>مانده</span><span>${n$(Math.max(0,c.total-paid))}</span></div></section></div>`;
}
ACT.oopen=a=>{S.ui.ordSel=a.dataset.id;renderAll();window.scrollTo(0,0)};
ACT.oback=()=>{S.ui.ordSel=null;renderAll()};
ACT.copyv=a=>copyText(a.dataset.v,"کد رهگیری کپی شد");
function setStatus(o,s,note){o.status=s;o.tl.push([s,jt(),note||""])}
ACT.ocancel=a=>{const o=S.orders.find(x=>x.id===a.dataset.id);modal({title:"لغو سفارش",body:`<p class="mp">با لغو سفارش، مبلغ پرداخت‌شده به کیف پول برمی‌گردد، اعتبار آزاد می‌شود و پاداش مربوط لغو می‌شود.</p>${sel("cReason","دلیل لغو",[["تغییر نیاز مشتری","تغییر نیاز مشتری"],["ثبت اشتباه سفارش","ثبت اشتباه سفارش"],["تأخیر در ارسال","تأخیر در ارسال"],["سایر","سایر"]],"")}`,actions:[{label:"انصراف",cls:"ghost"},{label:"لغو سفارش",cls:"danger",fn:()=>{
 const r=V("cReason");const back=o.pay.wallet+o.pay.gateway;if(back>0)wtx("بازگشت وجه",back,o.id);if(o.pay.credit>0){S.credit.used=Math.max(0,S.credit.used-o.pay.credit);S.ledger.unshift({t:jd(),order:o.id,amt:-o.pay.credit,type:"بازگشت"})}
 o.lines.forEach(l=>P(l.sku).stock+=l.qty);S.rewards.filter(x=>x.ref===o.id&&x.status==="pending").forEach(x=>x.status="cancelled");
 const inv=S.invoices.find(i=>i.order===o.id);if(inv){inv.cancelled=true;inv.paid=0}
 o.note=r;setStatus(o,"cancelled","لغو توسط نماینده: "+r);audit("سفارش",`لغو ${o.id}`);toast("سفارش لغو شد");renderAll()}}]})};
ACT.oreturn=a=>{const o=S.orders.find(x=>x.id===a.dataset.id);modal({title:"درخواست مرجوعی",body:`<p class="mp">درخواست شما به مالی و انبار ارسال می‌شود. پاداش‌های مربوط به این سفارش تا نتیجه بررسی متوقف می‌شوند.</p>${sel("rReason","دلیل مرجوعی",[["نقص فنی دستگاه","نقص فنی دستگاه"],["مغایرت با سفارش","مغایرت با سفارش"],["آسیب‌دیدگی در حمل","آسیب‌دیدگی در حمل"],["سایر","سایر"]],"")}${area("rNote","توضیح (اختیاری)")}`,actions:[{label:"انصراف",cls:"ghost"},{label:"ثبت درخواست",cls:"danger",fn:()=>{const r=V("rReason");o.note=r+(V("rNote")?" — "+V("rNote"):"");setStatus(o,"returned","درخواست مرجوعی ثبت شد؛ در انتظار بررسی مالی");S.rewards.filter(x=>x.ref===o.id&&["pending","approved","withdrawable"].includes(x.status)).forEach(x=>x.status="cancelled");audit("سفارش",`مرجوعی ${o.id}: ${r}`);toast("درخواست مرجوعی ثبت شد");renderAll()}}]})};
ACT.opay=a=>{const o=S.orders.find(x=>x.id===a.dataset.id);const inv=S.invoices.find(i=>i.order===o.id);payInvoice(inv)};
ACT.oadv=a=>{const o=S.orders.find(x=>x.id===a.dataset.id);const i=FLOW.indexOf(o.status);const nx=FLOW[i+1];if(!nx)return;
 if(nx==="shipped")o.track={carrier:"پست پیشتاز",code:String(Math.floor(3.5e11+Math.random()*1e11))};
 setStatus(o,nx,nx==="shipped"?"تحویل به شرکت حمل":nx==="delivered"?"تحویل به نماینده":nx==="completed"?"تسویه نهایی و تأیید مالی":"");
 if(nx==="delivered")S.rewards.filter(x=>x.ref===o.id&&x.status==="pending").forEach(x=>{x.status="approved"});
 if(nx==="completed")S.rewards.filter(x=>x.ref===o.id&&x.status==="approved").forEach(x=>{x.status="withdrawable"});
 toast("وضعیت به «"+ST[nx][0]+"» تغییر کرد");renderAll()};

/* ---------- فاکتورها ---------- */
const invFlt=[["all","همه"],["unpaid","پرداخت‌نشده"],["partial","پرداخت جزئی"],["paid","پرداخت‌شده"],["overdue","سررسیدگذشته"]];
VIEWS.invoices=()=>{
 const tab=S.ui.invTab,f=S.ui.invF;
 const invs=S.invoices.filter(i=>i.type==="invoice").map(i=>({i,x:invInfo(i)}));
 const due=invs.filter(a=>a.x.rem>0&&!a.i.cancelled).sort((a,b)=>a.i.due<b.i.due?-1:1)[0];
 const alert=due?`<div class="warnbox ${due.i.due<jd()?"bad":"warn"}">${due.i.due<jd()?"فاکتور "+due.i.id+" سررسیدگذشته است":"نزدیک‌ترین سررسید: "+due.i.id+" تا "+due.i.due}؛ مانده ${n$(due.x.rem)} تومان <button class="link" type="button" data-act="invpay" data-id="${due.i.id}">پرداخت</button></div>`:"";
 const head=vhead("پیش‌فاکتور و فاکتور","صدور، پرداخت و پیگیری تسویه",`<button class="b pri" type="button" data-go="shop">پیش‌فاکتور جدید</button>`)+alert+seg("invTab",[["inv","فاکتورها"],["pf","پیش‌فاکتورها"],["pay","تاریخچه پرداخت"]],tab);
 if(tab==="pf"){const pf=S.invoices.filter(i=>i.type==="proforma");return head+`<section class="card">${pf.length?`<div class="tw"><table><thead><tr><th>شماره</th><th>تاریخ</th><th>اعتبار تا</th><th>مبلغ (تومان)</th><th>وضعیت</th><th></th></tr></thead><tbody>${pf.map(i=>{const x=invInfo(i),exp=i.due<jd()&&!i.converted;return`<tr><td class="n">${i.id}</td><td class="n">${i.date}</td><td class="n">${i.due}</td><td class="n">${n$(x.total)}</td><td>${exp?chip("mute","منقضی"):chip(INVST[x.st][1],INVST[x.st][0])}</td><td><button class="link" type="button" data-act="invview" data-id="${i.id}">مشاهده</button> ${!i.converted&&!exp?`<button class="link" type="button" data-act="pf2cart" data-id="${i.id}">تبدیل به سفارش</button>`:""}</td></tr>`}).join("")}</tbody></table></div>`:empty("پیش‌فاکتوری ندارید","از سبد خرید پیش‌فاکتور صادر کنید")}</section>`}
 if(tab==="pay")return head+`<section class="card"><div class="tw"><table><thead><tr><th>شناسه</th><th>فاکتور</th><th>روش</th><th>مبلغ (تومان)</th><th>زمان</th><th>تطبیق</th></tr></thead><tbody>${S.payments.map(p=>`<tr><td class="n">${p.id}</td><td class="n">${p.inv}</td><td>${p.m}</td><td class="n">${n$(p.amt)}</td><td class="n">${p.t}</td><td>${chip(p.rec==="تطبیق‌شده"?"ok":"warn",p.rec)}</td></tr>`).join("")}</tbody></table></div></section>`;
 const L=invs.filter(a=>f==="all"||a.x.st===f);
 return head+`<section class="card">${seg("invF",invFlt,f)}${L.length?`<div class="tw"><table><thead><tr><th>شماره</th><th>سفارش</th><th>سررسید</th><th>مبلغ کل</th><th>پرداخت‌شده</th><th>وضعیت</th><th></th></tr></thead><tbody>${L.map(({i,x})=>`<tr><td class="n">${i.id}</td><td class="n">${i.order}</td><td class="n">${i.due}</td><td class="n">${n$(x.total)}</td><td class="n">${n$(i.paid)}</td><td>${chip(INVST[x.st][1],INVST[x.st][0])}</td><td><button class="link" type="button" data-act="invview" data-id="${i.id}">مشاهده</button> ${x.rem>0&&!i.cancelled?`<button class="link" type="button" data-act="invpay" data-id="${i.id}">پرداخت</button>`:""}</td></tr>`).join("")}</tbody></table></div>`:empty("فاکتوری در این دسته نیست")}</section>`;
};
function invoiceSheet(i){const x=invInfo(i),u=S.user,pf=i.type==="proforma";
 return`<div class="sheet-inv"><div class="si-h"><div><b>${pf?"پیش‌فاکتور":"فاکتور فروش"} ${i.id}</b><div class="lbl">تاریخ: ${i.date} · ${pf?"اعتبار تا":"سررسید"}: ${i.due}</div></div><div>${chip(INVST[x.st][1],INVST[x.st][0])}</div></div>
 <div class="si-p"><div><span class="lbl">فروشنده</span><b>شرکت توسن تکنو</b><span class="lbl">Smart Innovation</span></div><div><span class="lbl">خریدار</span><b>${u.biz}</b><span class="lbl">${u.name} · ${u.province}، ${u.city}</span></div></div>
 <div class="tw"><table><thead><tr><th>شرح</th><th>تعداد</th><th>قیمت واحد</th><th>جمع</th></tr></thead><tbody>${i.lines.map(l=>`<tr><td>${P(l.sku).name}${l.bundle?" "+chip("ok","بسته"):""}</td><td class="n">${fa(l.qty)}</td><td class="n">${n$(l.price??P(l.sku).price)}</td><td class="n">${n$(lineTotal(l))}</td></tr>`).join("")}</tbody></table></div>
 <div class="kvl"><span>جمع اقلام</span><span>${n$(x.sub)}</span>${x.disc?`<span>تخفیف</span><span>−${n$(x.disc)}</span>`:""}<span>ارزش افزوده (۱۰٪)</span><span>${n$(x.vat)}</span><span><b>مبلغ قابل پرداخت</b></span><span><b>${n$(x.total)}</b></span>${pf?"":`<span>پرداخت‌شده</span><span>${n$(i.paid)}</span><span>مانده</span><span>${n$(Math.max(0,x.rem))}</span>`}</div>
 ${i.lines.some(l=>l.bundle)?`<p class="lbl">جزئیات بسته: قیمت کارتخوان و کشلس طبق شرایط بسته ثبت شده است و تخفیف کارتخوان با حاشیه کشلس جبران می‌شود.</p>`:""}</div>`}
ACT.invview=a=>{const i=S.invoices.find(x=>x.id===a.dataset.id);const x=invInfo(i);const txt=`${i.type==="proforma"?"پیش‌فاکتور":"فاکتور"} ${i.id}\nتاریخ: ${i.date}\n${i.lines.map(l=>`${P(l.sku).name} × ${l.qty} = ${n$(lineTotal(l))}`).join("\n")}\nمبلغ کل: ${n$(x.total)} تومان`;
 modal({title:i.id,wide:true,body:invoiceSheet(i),actions:[{label:"بستن",cls:"ghost"},{label:"کپی خلاصه",fn:()=>{copyText(txt);return false}},...(x.rem>0&&i.type==="invoice"&&!i.cancelled?[{label:"پرداخت مانده",cls:"pri",fn:()=>{setTimeout(()=>payInvoice(i),0)}}]:[])]})};
ACT.invpay=a=>payInvoice(S.invoices.find(x=>x.id===a.dataset.id));
ACT.pf2cart=a=>{const i=S.invoices.find(x=>x.id===a.dataset.id);confirmBox("تبدیل به سفارش","اقلام این پیش‌فاکتور به سبد اضافه می‌شود و برای پرداخت آماده خواهید بود.",()=>{S.cart=i.lines.map(l=>({...l}));i.converted=true;S.ui.payOpen=true;const c=cartCalc();S.pay.wallet=Math.min(S.wallet,c.total);S.pay.credit=0;audit("پیش‌فاکتور",`تبدیل ${i.id} به سفارش`);go("cart")},"ادامه")};
function payInvoice(i){const x=invInfo(i);if(x.rem<=0){toast("این فاکتور تسویه شده است");return}
 modal({title:"پرداخت فاکتور "+i.id,body:`<div class="kvl"><span>مانده فاکتور</span><span><b>${n$(x.rem)}</b></span><span>موجودی کیف پول</span><span>${n$(S.wallet)}</span></div>${field("ipAmt","مبلغ پرداخت (تومان)",faSep(x.rem),{im:"numeric"})}${sel("ipSrc","روش پرداخت",[["wallet","کیف پول"],["gw","درگاه آنلاین"]],"wallet")}`,actions:[{label:"انصراف",cls:"ghost"},{label:"پرداخت",cls:"pri",fn:()=>{const amt=Math.min(num(V("ipAmt")),x.rem),src=V("ipSrc");if(!(amt>0)){toast("مبلغ را وارد کنید");return false}if(src==="wallet"&&amt>S.wallet){toast("موجودی کیف پول کافی نیست");return false}
  const done=()=>{if(src==="wallet")wtx("پرداخت فاکتور",-amt,i.id);i.paid+=amt;S.payments.unshift({id:"PY-"+(8900+S.payments.length),inv:i.id,amt,m:src==="wallet"?"کیف پول":"درگاه آنلاین",t:jt(),rec:src==="wallet"?"تطبیق‌شده":"در انتظار تطبیق"});
   const o=S.orders.find(o=>o.id===i.order);if(o&&o.status==="awaiting_payment"&&invInfo(i).rem<=0){o.pay[src==="wallet"?"wallet":"gateway"]+=amt;setStatus(o,"paid","پرداخت کامل ثبت شد");setStatus(o,"processing","سفارش وارد صف پردازش شد");const q=sum(o.lines.filter(l=>P(l.sku).cat==="pos"),l=>l.qty);if(q)S.rewards.unshift({id:"RW-"+(3411+S.rewards.length),type:"فروش کارتخوان",desc:`${q} دستگاه · سفارش ${o.id}`,amt:q*REWARD_POS,status:"pending",ref:o.id})}else if(o){o.pay[src==="wallet"?"wallet":"gateway"]+=amt}
   audit("پرداخت",`${n$(amt)} تومان برای ${i.id}`);toast("پرداخت ثبت شد");renderAll()};
  if(src==="gw"){setTimeout(()=>gateway(amt,done),0)}else done()}}]})}

