/* ---------- کیف پول ---------- */
VIEWS.wallet=()=>{
 const f=S.ui.txF,q=S.ui.txQ.trim();
 const L=[...S.txs].reverse().filter(t=>(f==="all"||(f==="in"&&t.amt>0)||(f==="out"&&t.amt<0))&&(!q||t.ref.includes(q)||t.type.includes(q)||t.id.includes(q)));
 const ver=S.banks.some(b=>b.status==="verified");
 return vhead("کیف پول","موجودی، برداشت و انتقال؛ همه حرکت‌ها ثبت و قابل پیگیری است",`<button class="b pri" type="button" data-act="topup">شارژ کیف پول</button><button class="b" type="button" data-act="withdraw">برداشت به حساب</button><button class="b" type="button" data-act="transfer">انتقال به نماینده</button>`)+
 `<div class="grid4">${stat("موجودی کیف پول",mn(S.wallet))}${stat("پاداش در انتظار",mn(rwSum("pending")),"هنوز قابل برداشت نیست")}${stat("پاداش تأییدشده",mn(rwSum("approved")),"در انتظار آزادسازی")}${stat("پاداش قابل برداشت",mn(rwSum("withdrawable")),`<button class="link" type="button" data-go="rewards">انتقال به کیف پول</button>`)}</div>
 ${ver?"":`<div class="warnbox bad">حساب بانکی تأییدشده ندارید؛ برداشت نقدی تا تأیید شبا ممکن نیست.</div>`}
 <section class="card"><div class="toolbar">${seg("txF",[["all","همه"],["in","واریز"],["out","برداشت"]],f)}<label class="fld grow"><span>جستجو</span><input id="txQ" data-in="txq" value="${esc(S.ui.txQ)}" placeholder="شناسه، مرجع یا نوع…"></label><button class="b" type="button" data-act="txcsv">خروجی CSV</button></div>
 ${L.length?`<div class="tw"><table><thead><tr><th>شناسه</th><th>نوع</th><th>مبلغ</th><th>قبل</th><th>بعد</th><th>مرجع</th><th>وضعیت</th><th>زمان</th><th>ثبت‌کننده</th></tr></thead><tbody>${L.map(t=>`<tr><td class="n">${t.id}</td><td>${t.type}</td><td class="n"><b class="${t.amt<0?"neg":"pos"}">${t.amt<0?"−":"+"}${n$(Math.abs(t.amt))}</b></td><td class="n">${n$(t.before)}</td><td class="n">${n$(t.after)}</td><td>${t.ref}</td><td>${chip(t.status==="موفق"?"ok":"warn",t.status)}</td><td class="n">${t.t}</td><td>${t.actor}</td></tr>`).join("")}</tbody></table></div>`:empty("تراکنشی پیدا نشد")}</section>`;
};
INP.txq=t=>{S.ui.txQ=t.value;renderAll();const e=$("txQ");if(e){e.focus();e.setSelectionRange(e.value.length,e.value.length)}};
ACT.txcsv=()=>textModal("خروجی تراکنش‌ها",toCSV(["شناسه","نوع","مبلغ","مانده قبل","مانده بعد","مرجع","وضعیت","زمان","ثبت‌کننده"],S.txs.map(t=>[t.id,t.type,t.amt,t.before,t.after,t.ref,t.status,t.t,t.actor])));
ACT.topup=()=>modal({title:"شارژ کیف پول",body:`${field("tpAmt","مبلغ (تومان)",faSep(50000000),{im:"numeric"})}<p class="lbl">حداقل مبلغ شارژ ۱٬۰۰۰٬۰۰۰ تومان است. پرداخت از درگاه بانکی (نمونه) انجام می‌شود.</p>`,actions:[{label:"انصراف",cls:"ghost"},{label:"پرداخت و شارژ",cls:"pri",fn:()=>{const a=num(V("tpAmt"));if(a<1e6){toast("حداقل مبلغ شارژ ۱٬۰۰۰٬۰۰۰ تومان است");return false}setTimeout(()=>gateway(a,()=>{wtx("شارژ کیف پول",a,"درگاه · PG-"+(78000+S.txs.length));audit("کیف پول",`شارژ ${n$(a)} تومان`);toast("کیف پول شارژ شد");renderAll()}),0)}}]});
