ACT.tknew=()=>{tkFile="";modal({title:"تیکت جدید",body:`<div class="fgrid">${sel("tkCat","دسته",[["سفارش","سفارش"],["پرداخت","پرداخت"],["کیف پول","کیف پول"],["پاداش","پاداش"],["فنی","فنی"],["سایر","سایر"]],"سفارش")}${sel("tkPri","اولویت",[["کم","کم"],["متوسط","متوسط"],["زیاد","زیاد"]],"متوسط")}</div>${field("tkSub","موضوع","")}${area("tkMsg","شرح مشکل","","جزئیات را بنویسید؛ شماره سفارش یا فاکتور کمک می‌کند")}<label class="b sm filebtn">پیوست فایل<input type="file" id="tkFile" hidden data-in="tkfile"></label> <span class="lbl" id="tkFn"></span>`,actions:[{label:"انصراف",cls:"ghost"},{label:"ثبت تیکت",cls:"pri",fn:()=>{if(!V("tkSub").trim()||!V("tkMsg").trim()){toast("موضوع و شرح مشکل را بنویسید");return false}
 const id="TK-"+(2032+S.tickets.length-2);S.tickets.unshift({id,cat:V("tkCat"),pri:V("tkPri"),subject:V("tkSub").trim(),status:"open",files:[],msgs:[{from:"me",text:V("tkMsg").trim(),t:jt(),file:tkFile}]});audit("پشتیبانی",`ثبت ${id}`);S.ui.tkSel=id;toast("تیکت ثبت شد");renderAll()}}]})};
ACT.tksend=a=>{const t=S.tickets.find(x=>x.id===a.dataset.id),m=V("tkReply").trim();if(!m){toast("متن پیام خالی است");return}t.msgs.push({from:"me",text:m,t:jt(),file:tkFile});t.status="open";tkFile="";toast("پیام ارسال شد");renderAll()};
ACT.tkclose=a=>confirmBox("بستن تیکت","پس از بستن، امکان ارسال پیام جدید وجود ندارد.",()=>{S.tickets.find(x=>x.id===a.dataset.id).status="closed";audit("پشتیبانی","بستن تیکت "+a.dataset.id);renderAll()},"بستن");

