/* ============================================================
   ویو موتور قیمت‌گذاری: شبیه‌ساز + پنل تنظیم قوانین
   ============================================================ */
VIEWS.pricing = () => {
  loadPricingConfig();
  const tier = (S.user && S.user.tier) || "bronze";
  const tierLabels = {bronze:"برنزی",silver:"نقره‌ای",gold:"طلایی",platinum:"پلاتینیوم",diamond:"الماس"};
  const simQty = S.ui.simQty || 10;
  const simSku = S.ui.simSku || "T800";
  const dp = dynamicUnitPrice(simSku, simQty);
  const p = P(simSku);
  const summary = pricingSummary([{sku:simSku, qty:simQty, price:dp.final}]);

  // محاسبه جدول شبیه‌سازی برای چند حجم
  const simRows = [1,5,10,20,50].map(q => {
    const d = dynamicUnitPrice(simSku, q);
    return {q, ...d};
  });

  return vhead("موتور قیمت‌گذاری پویا", "شبیه‌ساز قیمت + تنظیم قوانین توسط مدیر فروش",
    `<button class="b" type="button" data-go="shop">بازگشت به فروشگاه</button>`) +

  // ----- تب‌ها -----
  seg("priceTab", [["sim","شبیه‌ساز قیمت"],["rules","تنظیم قوانین"],["loyalty","سطح وفاداری"]], S.ui.priceTab || "sim") +

  // ===== شبیه‌ساز =====
  ((S.ui.priceTab || "sim") === "sim" ? `
  <div class="bgrid">
    <section class="card">
      <h3>شبیه‌ساز قیمت واحد</h3>
      <p class="lbl">قبل از ساخت سبد، ببینید با چه حجمی چه قیمتی می‌گیرید.</p>
      <div class="fgrid">
        ${sel("simSku", "محصول", PRODUCTS.filter(x=>x.cat==="pos").map(x=>[x.sku, x.name]), simSku)}
        ${field("simQty", "تعداد کارتخوان", fa(simQty), {im:"numeric"})}
      </div>
      <div class="mrow" style="margin-top:12px">
        <button class="b pri" type="button" data-act="runSim">محاسبه قیمت</button>
      </div>

      <div class="kvl" style="margin-top:18px;padding:14px;background:var(--blue-soft);border-radius:12px">
        <span>قیمت پایه</span><span>${n$(dp.base)}</span>
        <span>تخفیف حجمی</span><span>${(dp.discountPct*100 - (PRICING.tierDiscount[tier]||0)*100).toFixed(1)}٪ (${dp.volumeTier})</span>
        <span>تخفیف وفاداری (${tierLabels[tier]})</span><span>${((PRICING.tierDiscount[tier]||0)*100).toFixed(0)}٪</span>
        <span>تخفیف کل</span><span><b>${(dp.discountPct*100).toFixed(1)}٪</b></span>
        <span>قیمت نهایی واحد</span><span style="font-size:18px;color:var(--blue)"><b>${n$(dp.final)}</b></span>
        <span>جمع برای ${fa(simQty)} دستگاه</span><span><b>${n$(dp.final * simQty)}</b></span>
        ${dp.marginProtected ? `<span>وضعیت حاشیه</span><span class="neg">کف حاشیه اعمال شد</span>` : `<span>وضعیت حاشیه</span><span class="pos">سالم</span>`}
      </div>
    </section>

    <section class="card">
      <h3>جدول مقایسه حجم</h3>
      <div class="tw"><table>
        <thead><tr><th>تعداد</th><th>سطح حجمی</th><th>تخفیف</th><th>قیمت واحد</th><th>جمع</th></tr></thead>
        <tbody>
          ${simRows.map(r => `<tr class="${r.q===simQty?"me":""}">
            <td class="n">${fa(r.q)}</td>
            <td>${r.volumeTier}</td>
            <td class="n">${(r.discountPct*100).toFixed(1)}٪</td>
            <td class="n">${n$(r.final)}</td>
            <td class="n"><b>${n$(r.final * r.q)}</b></td>
          </tr>`).join("")}
        </tbody>
      </table></div>
      <p class="lbl" style="margin-top:10px">سطح وفاداری فعلی شما (<b>${tierLabels[tier]}</b>) در همه ردیف‌ها اعمال شده است.</p>
    </section>
  </div>
  ` : "") +

  // ===== تنظیم قوانین =====
  ((S.ui.priceTab) === "rules" ? `
  <section class="card">
    <h3>تنظیم قوانین قیمت‌گذاری <small>فقط مدیر فروش</small></h3>
    <p class="lbl">تغییرات بلافاصله روی قیمت‌های سبد و شبیه‌ساز اعمال می‌شود.</p>

    <h4 class="h4">حداقل حاشیه سود</h4>
    <div class="fgrid">
      ${field("cfgMargin", "حداقل حاشیه (٪)", fa(Math.round(PRICING.minMarginPct*100)), {im:"numeric"})}
      ${field("cfgRatio", "حداقل نسبت کشلس به کارتخوان", String(PRICING.minCashlessRatio), {im:"decimal"})}
    </div>

    <h4 class="h4">پله‌های تخفیف حجمی</h4>
    <div class="tw"><table>
      <thead><tr><th>از</th><th>تا</th><th>برچسب</th><th>تخفیف (٪)</th></tr></thead>
      <tbody>
        ${PRICING.volumeTiers.map((t,i) => `<tr>
          <td><input class="inp" id="vtMin${i}" value="${t.minQty}" style="width:60px;text-align:center"></td>
          <td><input class="inp" id="vtMax${i}" value="${t.maxQty}" style="width:60px;text-align:center"></td>
          <td><input class="inp" id="vtLabel${i}" value="${t.label}" style="width:100px"></td>
          <td><input class="inp" id="vtDisc${i}" value="${Math.round(t.discount*100)}" style="width:60px;text-align:center"> ٪</td>
        </tr>`).join("")}
      </tbody>
    </table></div>

    <h4 class="h4">تخفیف سطح وفاداری</h4>
    <div class="fgrid">
      ${["bronze","silver","gold","platinum","diamond"].map(t =>
        field("td_"+t, tierLabels[t], fa(Math.round((PRICING.tierDiscount[t]||0)*100)), {im:"numeric"})
      ).join("")}
    </div>

    <div class="mrow" style="margin-top:16px">
      <button class="b pri" type="button" data-act="savePricing">ذخیره قوانین</button>
      <button class="b" type="button" data-act="resetPricing">بازگردانی به پیش‌فرض</button>
    </div>
  </section>
  ` : "") +

  // ===== سطح وفاداری =====
  ((S.ui.priceTab) === "loyalty" ? `
  <section class="card">
    <h3>سطح وفاداری شما و تأثیر آن روی قیمت</h3>
    <div class="tier" style="margin-bottom:16px">
      <div class="medal">${tierLabels[tier].slice(0,3)}</div>
      <div>
        <div style="font-size:18px">${tierLabels[tier]}</div>
        <div class="lbl">تخفیف فعلی شما: <b>${((PRICING.tierDiscount[tier]||0)*100).toFixed(0)}٪</b></div>
      </div>
    </div>

    <div class="tw"><table>
      <thead><tr><th>سطح</th><th>تخفیف قیمت</th><th>وضعیت شما</th></tr></thead>
      <tbody>
        ${["bronze","silver","gold","platinum","diamond"].map(t => `<tr class="${t===tier?"me":""}">
          <td>${tierLabels[t]}</td>
          <td class="n">${((PRICING.tierDiscount[t]||0)*100).toFixed(0)}٪</td>
          <td>${t===tier ? chip("ok","سطح فعلی") : ""}</td>
        </tr>`).join("")}
      </tbody>
    </table></div>

    <p class="lbl" style="margin-top:12px">
      سطح وفاداری بر اساس خرید تجمعی شما محاسبه می‌شود و مستقیماً روی قیمت واحد همه کارتخوان‌ها تأثیر می‌گذارد.
      هر چه سطح بالاتر باشد، قیمت تمام‌شده برای شما پایین‌تر است.
    </p>
  </section>
  ` : "");
};

// Actions for pricing view
ACT.runSim = () => {
  S.ui.simQty = Math.max(1, num(V("simQty")) || 10);
  S.ui.simSku = V("simSku") || "T800";
  S.ui.priceTab = "sim";
  renderAll();
};

ACT.savePricing = () => {
  const margin = Math.max(0, Math.min(50, num(V("cfgMargin")))) / 100;
  const ratio  = Math.max(0, parseFloat(V("cfgRatio")) || 1);

  const volumeTiers = PRICING.volumeTiers.map((t,i) => ({
    minQty: num(V("vtMin"+i)) || t.minQty,
    maxQty: num(V("vtMax"+i)) || t.maxQty,
    label: (V("vtLabel"+i) || t.label).trim(),
    discount: Math.max(0, Math.min(30, num(V("vtDisc"+i)))) / 100
  }));

  const tierDiscount = {};
  ["bronze","silver","gold","platinum","diamond"].forEach(t => {
    tierDiscount[t] = Math.max(0, Math.min(15, num(V("td_"+t)))) / 100;
  });

  S.pricingConfig = {
    minMarginPct: margin,
    minCashlessRatio: ratio,
    volumeTiers,
    tierDiscount
  };
  loadPricingConfig();
  audit("قیمت‌گذاری", "قوانین قیمت‌گذاری به‌روزرسانی شد");
  toast("قوانین قیمت‌گذاری ذخیره شد");
  renderAll();
};

ACT.resetPricing = () => {
  confirmBox("بازگردانی قوانین", "همه تنظیمات به مقادیر پیش‌فرض کارخانه برمی‌گردد. ادامه؟", () => {
    delete S.pricingConfig;
    PRICING = JSON.parse(JSON.stringify(PRICING_DEFAULTS));
    audit("قیمت‌گذاری", "قوانین به پیش‌فرض بازگردانده شد");
    toast("قوانین به پیش‌فرض بازگشت");
    renderAll();
  }, "بازگردانی");
};

INP.priceTab = (el) => { S.ui.priceTab = el.value || el.dataset?.v; renderAll(); };

function renderDash(){
 const av=creditAvail(),used=S.credit.used,lim=S.credit.limit,pct=Math.round(used/lim*100),db=debt();
 const dueInv=S.invoices.filter(i=>i.type==="invoice"&&!i.cancelled&&invInfo(i).rem>0).map(i=>i.due).sort()[0];
 partial("kpis",`<section class="card k"><div class="lbl">موجودی کیف پول</div><div class="big">${n$(S.wallet)}<u>تومان</u></div><div class="row"><span>برداشت فقط به شبای تأییدشده</span></div></section>
 <section class="card k"><div class="lbl">اعتبار قابل استفاده</div><div class="big">${n$(av)}<u>تومان</u></div><div class="meter"><i style="width:${pct}%;background:var(--ink)"></i><i style="width:${100-pct}%;background:var(--blue)"></i></div><div class="row"><span>استفاده‌شده ${mil(used)}</span><span>سقف ${mil(lim)}</span></div></section>
 <section class="card k"><div class="lbl">مانده بدهی</div><div class="big">${n$(db)}<u>تومان</u></div><div class="row"><span>سررسید بعدی</span><b>${dueInv||"—"}</b></div></section>
 <section class="card k"><div class="lbl">پاداش قابل برداشت</div><div class="big">${n$(rwSum("withdrawable"))}<u>تومان</u></div><div class="row"><span>در انتظار تأیید</span><b>${n$(rwSum("pending")+rwSum("approved"))}</b></div></section>
 <section class="card k"><div class="lbl">هدف ماهانه کارتخوان</div><div class="big">۷<span style="font-size:18px"> / ۱۰</span></div><div class="meter"><i style="width:70%;background:var(--blue)"></i></div><div class="row"><span>۷۰٪ پیشرفت</span><b>پاداش هدف: ۳ میلیون</b></div></section>
 <section class="card k"><div class="lbl">نسبت کشلس به کارتخوان</div><div class="big">۱٫۴</div><div class="row"><span>هدف حداقلی: ۱٫۲</span><b class="pos">بالای هدف</b></div></section>`);
 partial("dashOrders",S.orders.slice(0,4).map(o=>`<tr class="clk" data-act="dgo" data-id="${o.id}"><td class="n">${o.id}</td><td>${ordShort(o)}</td><td>${stc(o.status)}</td><td>${stepsBar(o.status)}</td><td class="n">${n$(ordTotal(o))}</td></tr>`).join(""));
 partial("dashInv",S.invoices.filter(i=>i.type==="invoice").slice(0,3).map(i=>{const x=invInfo(i);return`<tr><td class="n">${i.id}</td><td class="n">${n$(x.total)}</td><td>${chip(INVST[x.st][1],INVST[x.st][0])}</td><td><button class="link" type="button" data-act="invview" data-id="${i.id}">مشاهده</button></td></tr>`}).join(""));
 partial("dashNews",S.news.slice(0,3).map(n=>`<div class="it"><div class="t"><span>${n.title}</span>${n.read?"":'<span class="unread"></span>'}</div><div class="d">${n.pin?'<span class="pin">سنجاق‌شده</span> · ':""}${n.type} · ${n.date}</div></div>`).join(""));
}
ACT.dgo=a=>{S.ui.ordSel=a.dataset.id;go("orders")};
Object.assign(VIEWS,{});



